<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">juliaup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rc</span></span>
